-- 21-검증. 091000 적용 직후 (조회 전용). 모든 ok 가 true 여야 합니다.
SELECT no, item, actual, expected,
       CASE WHEN expected = '기록용' THEN NULL ELSE actual IS NOT DISTINCT FROM expected END AS ok
FROM (VALUES
    (1, '승인시각 보호 트리거(머리글 13종, 활성)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_approval_times' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgenabled <> 'D'), '13'),
    (2, '승인시각 보호 함수', (to_regprocedure('public.enforce_daily_log_approval_times()') IS NOT NULL)::text, 'true'),
    (3, '정정 허용 확인 함수', (to_regprocedure('public.daily_log_correction_allows(text, uuid)') IS NOT NULL)::text, 'true'),
    (4, '트리거 실행 시점 BEFORE·행 단위(INSERT/UPDATE/DELETE)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_approval_times' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgtype = 31), '13'),
    (5, '감사 트리거 유지(일지 25)', (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_audit_row_change' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D'), '25'),
    (6, '회사 범위 정책 유지(095000)', (SELECT count(*)::text FROM pg_policies WHERE schemaname = 'public' AND tablename = ANY (ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs', 'daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) AND policyname = tablename || '_org_access'), '25'),
    (7, '094000·096000 아직 없음', ((SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_item_parent_unlocked' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_log_items', 'daily_temp_humidity_log_items', 'daily_sanitation_facility_log_items', 'daily_worker_hygiene_log_items', 'daily_cold_storage_hygiene_log_items', 'daily_process_control_bread_log_items', 'daily_material_storage_3f_log_items', 'daily_manufacturing_equipment_log_items', 'daily_air_conditioning_equipment_log_items', 'daily_hoist_inspection_log_items', 'daily_illumination_log_items', 'daily_material_receiving_inspection_log_items']::text[]) t)) AND tgenabled <> 'D') || '/' || (SELECT count(*)::text FROM pg_trigger WHERE tgname = 'trg_daily_log_edit_rights' AND tgrelid = ANY (ARRAY(SELECT to_regclass('public.' || t)::oid FROM unnest(ARRAY['daily_hygiene_logs', 'daily_temp_humidity_logs', 'daily_sanitation_facility_logs', 'daily_worker_hygiene_logs', 'daily_cold_storage_hygiene_logs', 'daily_process_control_bread_logs', 'daily_material_storage_3f_logs', 'daily_manufacturing_equipment_logs', 'daily_air_conditioning_equipment_logs', 'daily_hoist_inspection_logs', 'daily_illumination_logs', 'daily_material_receiving_inspection_logs', 'daily_raw_thawing_logs']::text[]) t)) AND tgenabled <> 'D')), '0/0')
) AS v(no, item, actual, expected)
ORDER BY no;
